def check_airport_code(S: str, T: str) -> str:
    def is_subsequence(small, large):
        it = iter(large)
        return all(char in it for char in small)

    # Check if T can be formed by a subsequence of length 3 from S
    if is_subsequence(T.lower(), S):
        return "Yes"

    # Check if T can be formed by a subsequence of length 2 from S and appending 'X'
    if T[-1] == 'X' and is_subsequence(T[:2].lower(), S):
        return "Yes"

    return "No"

S = input()
T = input()
print(check_airport_code(S, T))
